#!/usr/bin/env python3
"""Builds podcast_script_inll{,_fr,_de,_lb}.md from build/inll_src/<lang>.txt
(body turns: 'A: text' = Anna, 'T: text' = Tom, 'C: text' = Anna's closing line, followed by the standard outro)
+ the standard Biergerpakt intro/outro taken from the kjt scripts. Edit the .txt files and re-run; do not edit the .md."""
KEY = "inll"
HEAD = {
 "en": ('# Podcast Script — "INLL – Learning Luxembourgish and Other Languages"', "**Part of the Biergerpakt programme**", "**Hosts:** Anna (woman) and Tom (man)", "**Length:** about {MIN} minutes — spoken slowly, in simple English"),
 "fr": ("# Script du podcast — « L'INLL – Apprendre le luxembourgeois et d'autres langues »", "**Dans le cadre du programme Biergerpakt**", "**Animateurs :** Anna (femme) et Tom (homme)", "**Durée :** environ {MIN} minutes — parlé lentement, dans un français simple"),
 "de": ("# Podcast-Skript — „Das INLL – Luxemburgisch und andere Sprachen lernen“", "**Teil des Biergerpakt-Programms**", "**Moderation:** Anna (Frau) und Tom (Mann)", "**Länge:** etwa {MIN} Minuten — langsam gesprochen, in einfachem Deutsch"),
 "lb": ("# Podcast-Skript — „Den INLL – Lëtzebuergesch an aner Sprooche léieren“", "**Deel vum Biergerpakt-Programm**", "**Moderatioun:** Anna (Fra) an Tom (Mann)", "**Längt:** ongeféier {MIN} Minutten — lues geschwat, an engem einfache Lëtzebuergesch"),
}
MIN = {"en": 10, "fr": 10, "de": 11, "lb": 10}   # estimate before recording; update after
OUTRO_START = {"en": "This podcast is part of the Biergerpakt, a programme", "fr": "Ce podcast fait partie du Biergerpakt, un programme",
               "de": "Dieser Podcast ist Teil des Biergerpakt, ein Programm", "lb": "Dëse Podcast ass Deel vum Biergerpakt, engem Programm"}
SOURCES = {
 "en": "*Sources: inll.lu (Institut national des langues Luxembourg), consulted on 27 November 2026 in English — home page (courses for private and professional purposes, certification, Sproochentest, trainings, MyINL enrolment portal, three sites, beginners' podcast in Luxembourgish, events); \"Institute\" (public centre for adult learning and certification of modern language skills; promotes multilingualism, employability, social integration and intercultural exchange; trains language teachers; three administrative languages, many expatriates and cross-border workers; national certification centre for Luxembourgish; media library, restaurant, language tandems); \"Sites\" (Luxembourg-Glacis, Belval in Esch-sur-Alzette, Mersch; languages per site); \"Courses\" (languages; CEFR levels A1 to C2; standard, compact, blended, e-learning, hybrid, combined and workshop-type courses; Moving Languages: Luxembourgish or French, eight weeks, three hours a day, in the target language from the start, aim A2 speaking; guided autonomous learning of Luxembourgish with live video sessions, weekly online support and a speaking test at INLL Glacis; semesters starting in September and February; placement test and interview; fees on MyINL, books not included); \"FAQ\" (adults only; taught in the target language from the first lesson; enrolment steps and recommended level; beginners may choose A1; pre-test and orientation interview, all year; reduced fee for people sent by ADEM, SNAS, ONA or a social office and for signatories of the reception and integration contract, with a voucher; continuous assessment and oral test; skills assessment and certificate of attendance on MyINL; no citizenship courses for nationality: Adult Education Service and its partners; Sproochentest: only certificate recognised for nationality, unlimited validity, unlimited retakes after the previous result, no refund for no-shows without a valid reason, Luxembourg City and Esch-sur-Alzette); \"Sproochentest\" (Grand-Ducal regulation of 22 July 2019; speaking A2, about 10 minutes, interview on one of two topics and description of a picture; listening B1, three texts, answers on a tablet; same half day; pass with at least half of the points in speaking, or an average of at least 50% of both parts; registration via MyINL; very high demand; adapted conditions with a medical document; sample materials); \"Certificates\" (LAF diploma A2 to C1, ZLO spelling certificate, international exams for German, English, French, Italian, Dutch, Portuguese and Spanish); \"LAF\" (four skills, partial registration possible, independent of the courses, useful for professional purposes); \"ZLO\" (multiple-choice spelling test); \"Trainings\" (ZLLL for teachers of Luxembourgish to adults, CELVP for teaching languages for professional purposes, Komco communication coaching); \"Legislation\" (law of 8 March 2023 creating the INLL). Ministry and Moving Languages background (method inspired by Liechtenstein Languages, movement and the five senses, developed with the Adult Education Service): gouvernement.lu press releases of the Ministry of Education, Children and Youth (Feb. 2024, Jan. 2026) and luxembourg.public.lu (Introduction to Luxembourgish). Durable wording only: no fees (the Sproochentest fee is set by regulation), no exact numbers of courses, learners, languages per site or staff, no dates of sessions, no phone numbers, no names; the beginners' podcast (Poterkëscht) and the diplomas (LAF, ZLO, ZLLL, Komco, CELVP) are described, not named. Language leave is explained in the lifelong-learning episode. The opening scene is an illustration by the hosts. General information only. Accurate as of November 2026.*",
 "fr": "*Sources : inll.lu (Institut national des langues Luxembourg), consulté le 27 novembre 2026 — page d'accueil ; « Institut » (centre public de formation des adultes et de certification des compétences en langues vivantes ; multilinguisme, employabilité, intégration sociale, échanges interculturels ; formation des enseignants ; centre national de certification pour le luxembourgeois ; médiathèque, restaurant, tandems) ; « Sites » (Luxembourg-Glacis, Belval à Esch-sur-Alzette, Mersch) ; « Cours » (langues ; niveaux A1 à C2 du CECRL ; cours standard, compacts, mixtes, en ligne, hybrides, ateliers ; Moving Languages : luxembourgeois ou français, huit semaines, trois heures par jour, objectif A2 à l'oral ; apprentissage autonome guidé du luxembourgeois ; semestres de septembre et de février ; tarifs sur MyINL, manuels non compris) ; « FAQ » (adultes uniquement ; cours dans la langue cible dès la première leçon ; inscription et niveau recommandé ; pré-test et entretien d'orientation ; tarif réduit avec un bon pour les personnes envoyées par l'ADEM, le SNAS, l'ONA ou un office social et pour les signataires du contrat d'accueil et d'intégration ; évaluation continue et test oral ; bilan de compétences et certificat de participation ; pas de cours de citoyenneté : Service de la formation des adultes et partenaires ; Sproochentest : seul certificat reconnu pour la nationalité, validité illimitée, nombre de tentatives illimité, pas de remboursement en cas d'absence sans motif valable) ; « Sproochentest » (règlement grand-ducal du 22 juillet 2019 ; oral A2, environ 10 minutes ; compréhension B1, trois textes, réponses sur tablette ; même demi-journée ; règles de réussite ; inscription par MyINL ; aménagements avec un document médical ; exemples) ; « Certifications » (diplôme LAF A2 à C1, certificat d'orthographe ZLO, examens internationaux) ; « LAF » ; « ZLO » ; « Formations » (ZLLL, CELVP, Komco) ; « Législation » (loi du 8 mars 2023). Ministère et Moving Languages : communiqués du Ministère de l'Éducation nationale, de l'Enfance et de la Jeunesse sur gouvernement.lu (févr. 2024, janv. 2026) et luxembourg.public.lu. Formulations durables uniquement : pas de tarifs, pas de nombres exacts, pas de dates de sessions, pas de numéros de téléphone, pas de noms. Le congé linguistique est expliqué dans l'épisode sur la formation tout au long de la vie. La scène d'ouverture est une illustration des animateurs. Informations générales uniquement. Exact en novembre 2026.*",
 "de": "*Quellen: inll.lu (Institut national des langues Luxembourg), abgerufen am 27. November 2026 — Startseite; „Institut“ (öffentliches Zentrum für Erwachsenenbildung und Zertifizierung von Sprachkenntnissen; Mehrsprachigkeit, Beschäftigungsfähigkeit, soziale Integration, interkultureller Austausch; Ausbildung von Lehrkräften; nationales Zertifizierungszentrum für Luxemburgisch; Mediathek, Restaurant, Sprachtandems); „Standorte“ (Luxemburg-Glacis, Belval in Esch-sur-Alzette, Mersch); „Kurse“ (Sprachen; Niveaus A1 bis C2 des GER; Standard-, Kompakt-, Blended-, Online-, Hybridkurse, Workshops; Moving Languages: Luxemburgisch oder Französisch, acht Wochen, drei Stunden pro Tag, Ziel A2 im Sprechen; begleitetes selbstständiges Lernen von Luxemburgisch; Semester ab September und Februar; Preise auf MyINL, Bücher nicht inbegriffen); „FAQ“ (nur Erwachsene; Unterricht in der Zielsprache ab der ersten Stunde; Anmeldung und empfohlenes Niveau; Vortest und Orientierungsgespräch; ermäßigter Preis mit Gutschein für Menschen, die von ADEM, SNAS, ONA oder einem Sozialamt geschickt werden, und für Unterzeichner des Aufnahme- und Integrationsvertrags; laufende Bewertung und mündlicher Test; Kompetenzbescheinigung und Teilnahmebescheinigung; keine Staatsbürgerkunde-Kurse: Dienst für Erwachsenenbildung und Partner; Sproochentest: einzige anerkannte Bescheinigung für die Staatsangehörigkeit, unbegrenzt gültig, beliebig oft wiederholbar, keine Erstattung bei Nichterscheinen ohne triftigen Grund); „Sproochentest“ (großherzogliche Verordnung vom 22. Juli 2019; Sprechen A2, etwa 10 Minuten; Hörverstehen B1, drei Texte, Antworten auf einem Tablet; derselbe halbe Tag; Bestehensregeln; Anmeldung über MyINL; angepasste Bedingungen mit ärztlichem Dokument; Beispiele); „Zertifikate“ (Diplom LAF A2 bis C1, Rechtschreibzertifikat ZLO, internationale Prüfungen); „LAF“; „ZLO“; „Ausbildungen“ (ZLLL, CELVP, Komco); „Gesetzgebung“ (Gesetz vom 8. März 2023). Ministerium und Moving Languages: Pressemitteilungen des Ministeriums für Bildung, Kinder und Jugend auf gouvernement.lu (Feb. 2024, Jan. 2026) und luxembourg.public.lu. Nur dauerhafte Angaben: keine Preise, keine genauen Zahlen, keine Prüfungstermine, keine Telefonnummern, keine Namen. Der Sprachurlaub wird in der Folge über lebenslanges Lernen erklärt. Die Eingangsszene ist eine Veranschaulichung der Moderatoren. Nur allgemeine Informationen. Stand: November 2026.*",
 "lb": "*Quellen: inll.lu (Institut national des langues Luxembourg), consultéiert de 27. November 2026; Communiquéë vum Educatiounsministère op gouvernement.lu a luxembourg.public.lu (Moving Languages). Fräi Iwwersetzung. Keng Präisser, keng genau Zuelen, keng Datumer vun Exame-Sessiounen, keng Telefonsnummeren a keng Nimm. Nëmmen allgemeng Informatiounen. Stand: November 2026.*",
}
def turns(path):
    return [l.rstrip("\n") for l in open(path, encoding="utf-8") if l.startswith("**ANNA") or l.startswith("**TOM")]
for lang in ("en", "fr", "de", "lb"):
    sfx = "" if lang == "en" else "_" + lang
    ref = turns(f"podcast_script_kjt{sfx}.md")
    intro, closing, last2 = ref[:3], ref[-3], ref[-2:]
    outro = closing[closing.index(OUTRO_START[lang]):]
    body = []
    for l in open(f"build/inll_src/{lang}.txt", encoding="utf-8"):
        l = l.strip()
        if not l: continue
        who, txt = l.split(": ", 1)
        assert who in ("A", "T", "C"), l[:30]
        if who == "C": txt += " " + outro
        body.append(f"**{'TOM' if who == 'T' else 'ANNA'}:** {txt}")
    assert len(body) == 46, (lang, len(body))
    seq = [x[2] for x in intro + body + last2]
    assert all(a != b for a, b in zip(seq, seq[1:])), (lang, "same speaker twice")
    head = [h.replace("{MIN}", str(MIN[lang])) for h in HEAD[lang]]
    out = "\n".join([head[0], "", *head[1:], "", "---", "", *intro, *body, *last2, "", "---", "", SOURCES[lang], ""])
    open(f"podcast_script_{KEY}{sfx}.md", "w", encoding="utf-8").write(out)
    t = turns(f"podcast_script_{KEY}{sfx}.md")
    print(lang, len(t), "turns;", "..." in out or "…" in out, "ellipsis;", sum(len(x.split(":** ",1)[1]) for x in t), "chars")
